import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs['target_snapshot'].copy()
    events = inputs['cdc_events'].copy()
    watermark = inputs['watermark'].copy()

    # Extract watermark high_ts (single value)
    if len(watermark) > 0:
        high_ts = watermark['high_ts'].iloc[0]
    else:
        high_ts = None

    # Keep only events strictly after the watermark (events <= high_ts already applied)
    if high_ts is not None:
        events = events[events['event_ts'] > high_ts]
    else:
        events = events.iloc[0:0]

    # Deterministic sequential application order: per item, by (event_ts, event_seq)
    events = events.sort_values(
        by=['item_id', 'event_ts', 'event_seq'],
        kind='mergesort'
    )

    # Initialize state from the target snapshot
    state = {}
    for _, row in target.iterrows():
        state[row['item_id']] = {
            'qty_on_hand': row['qty_on_hand'],
            'last_event_ts': row['last_event_ts'],
            'present': True,
        }

    # Apply events sequentially per item
    for _, ev in events.iterrows():
        item_id = ev['item_id']
        op = ev['op']
        qty = ev['qty']
        ts = ev['event_ts']

        if item_id not in state:
            state[item_id] = {
                'qty_on_hand': 0,
                'last_event_ts': None,
                'present': False,
            }

        s = state[item_id]

        if op == 'R':
            if not s['present']:
                s['qty_on_hand'] = 0
            s['qty_on_hand'] = s['qty_on_hand'] + qty
            s['present'] = True
        elif op == 'A':
            s['qty_on_hand'] = qty
            s['present'] = True
        elif op == 'D':
            s['present'] = False
            # qty_on_hand value is irrelevant once removed; keep as-is

        s['last_event_ts'] = ts

    # Build output: only items currently present
    rows = []
    for item_id, s in state.items():
        if s['present']:
            rows.append({
                'item_id': item_id,
                'qty_on_hand': s['qty_on_hand'],
                'last_event_ts': s['last_event_ts'],
            })

    new_snapshot = pd.DataFrame(rows, columns=['item_id', 'qty_on_hand', 'last_event_ts'])

    return {'new_snapshot': new_snapshot}
